26	struct BFS_F {
27	  uintE* Parents;
28	  BFS_F(uintE* _Parents) : Parents(_Parents) {}
29	  inline bool update (uintE s, uintE d) { //Update
30	    if(Parents[d] == UINT_E_MAX) { Parents[d] = s; return 1; }
31	    else return 0;
32	  }
33	  inline bool updateAtomic (uintE s, uintE d){ //atomic version of Update
34	    return (CAS(&Parents[d],UINT_E_MAX,s));
35	  }
36	  //cond function checks if vertex has been visited yet
37	  inline bool cond (uintE d) { return (Parents[d] == UINT_E_MAX); }
38	};
