17	template <class vertex>
18	void Compute(graph<vertex>& GA, commandLine P) {
19	  long n = GA.n;
20	  long* IDs = new long[n]; 
21	  {parallel_for(long i=0;i<n;i++) IDs[i] = i;} //initialize unique IDs
22	
23	  bool* frontier = newA(bool,n);
24	  {parallel_for(long i=0;i<n;i++) frontier[i] = 1;} 
