245	// Main edgeMap dispatch: decides between sparse and dense based on
246	// frontier size vs threshold (default: numEdges/20).
247	// If m + outDegrees > threshold, use dense mode; otherwise sparse.
248	template <class data, class vertex, class VS, class F>
249	vertexSubsetData<data> edgeMapData(graph<vertex>& GA, VS &vs, F f,
250	    intT threshold = -1, const flags& fl=0) {
251	  long numVertices = GA.n, numEdges = GA.m, m = vs.numNonzeros();
252	  if(threshold == -1) threshold = numEdges/20; //default threshold
253	  vertex *G = GA.V;
254	  if (numVertices != vs.numRows()) {
255	    cout << "edgeMap: Sizes Don't match" << endl;
256	    abort();
257	  }
258	  if (vs.size() == 0) return vertexSubsetData<data>(numVertices);
259	  uintT* degrees = NULL;
260	  vertex* frontierVertices = NULL;
261	  uintT outDegrees = 0;
262	  if(threshold > 0) { //compute sum of out-degrees if threshold > 0
263	    vs.toSparse();
264	    degrees = newA(uintT, m);
265	    frontierVertices = newA(vertex,m);
266	    {parallel_for (size_t i=0; i < m; i++) {
267	      uintE v_id = vs.vtx(i);
268	      vertex v = G[v_id];
269	      degrees[i] = v.getOutDegree();
270	      frontierVertices[i] = v;
271	    }}
272	    outDegrees = sequence::plusReduce(degrees, m);
273	    if (outDegrees == 0) return vertexSubsetData<data>(numVertices);
274	  }
275	  if (!(fl & no_dense) && m + outDegrees > threshold) {
276	    if(degrees) free(degrees);
277	    if(frontierVertices) free(frontierVertices);
278	    vs.toDense();
279	    return (fl & dense_forward) ?
280	      edgeMapDenseForward<data, vertex, VS, F>(GA, vs, f, fl) :
281	      edgeMapDense<data, vertex, VS, F>(GA, vs, f, fl);
282	  } else {
283	    auto vs_out =
284	      (should_output(fl) && fl & sparse_no_filter) ? // only call snof when we output
285	      edgeMapSparse_no_filter<data, vertex, VS, F>(GA, frontierVertices, vs, degrees, vs.numNonzeros(), f, fl) :
286	      edgeMapSparse<data, vertex, VS, F>(GA, frontierVertices, vs, degrees, vs.numNonzeros(), f, fl);
287	    free(degrees); free(frontierVertices);
288	    return vs_out;
289	  }
290	}
