378	// Applies f to each vertex in V (with associated data).
379	template <class F, class VS, typename std::enable_if<
380	  !std::is_same<VS, vertexSubset>::value, int>::type=0 >
381	void vertexMap(VS& V, F f) {
382	  size_t n = V.numRows(), m = V.numNonzeros();
383	  if(V.dense()) {
384	    parallel_for(long i=0;i<n;i++) {
385	      if(V.isIn(i)) {
386	        f(i, V.ithData(i));
387	      }
388	    }
389	  } else {
390	    parallel_for(long i=0;i<m;i++) {
391	      f(V.vtx(i), V.vtxData(i));
392	    }
393	  }
394	}
