414	// Returns the subset of V where filter(v) is true. Uses a dense representation
415	// (a boolean array of length n) for the result.
416	template <class F>
417	vertexSubset vertexFilter(vertexSubset V, F filter) {
418	  long n = V.numRows(), m = V.numNonzeros();
419	  V.toDense();
420	  bool* d_out = newA(bool,n);
421	  {parallel_for(long i=0;i<n;i++) d_out[i] = 0;}
422	  {parallel_for(long i=0;i<n;i++) if(V.d[i]) d_out[i] = filter(i);}
423	  return vertexSubset(n,d_out);
424	}
