448	template <class data, class F>
449	vertexSubset vertexFilter2(vertexSubsetData<data> V, F filter) {
450	  long n = V.numRows(), m = V.numNonzeros();
451	  if (m == 0) {
452	    return vertexSubset(n);
453	  }
454	  bool* bits = newA(bool, m);
455	  V.toSparse();
456	  {parallel_for(size_t i=0; i<m; i++) {
457	    auto t = V.vtxAndData(i);
458	    bits[i] = filter(std::get<0>(t), std::get<1>(t));
459	  }}
460	  auto v_imap = make_in_imap<uintE>(m, [&] (size_t i) { return V.vtx(i); });
461	  auto bits_m = make_in_imap<bool>(m, [&] (size_t i) { return bits[i]; });
462	  auto out = pbbs::pack(v_imap, bits_m);
463	  out.alloc = false;
464	  free(bits);
465	  return vertexSubset(n, out.size(), out.s);
466	}
