12	template <class data>
13	struct vertexSubsetData {
14	  using S = tuple<uintE, data>;
15	  using D = tuple<bool, data>;
16	
17	  // An empty vertex set.
18	  vertexSubsetData(size_t _n) : n(_n), m(0), d(NULL), s(NULL), isDense(0) { }
19	
20	  // A vertexSubset from array of vertex indices.
21	  vertexSubsetData(long _n, long _m, S* indices)
22	  : n(_n), m(_m), s(indices), d(NULL), isDense(0) { }
23	
24	  // A vertexSubset from boolean array giving number of true values.
25	  vertexSubsetData(long _n, long _m, D* _d)
26	  : n(_n), m(_m), s(NULL), d(_d), isDense(1) { }
27	
28	  // A vertexSubset from boolean array giving number of true values. Calculate
29	  // number of nonzeros and store in m.
30	  vertexSubsetData(long _n, D* _d)
31	  : n(_n), s(NULL), d(_d), isDense(1) {
32	    auto d_map = make_in_imap<size_t>(n, [&] (size_t i) { return (size_t)get<0>(_d[i]); });
33	    m = pbbs::reduce_add(d_map);
34	  }
35	
36	  vertexSubsetData()
37	  : n(0), m(0), s(NULL), d(NULL), isDense(0) { }
38	
39	  void del() {
40	    if (d != NULL) free(d);
41	    if (s != NULL) free(s);
42	  }
43	
44	  // Sparse
45	  inline uintE& vtx(const uintE& i) const { return std::get<0>(s[i]); }
46	  inline data& vtxData(const uintE& i) const { return std::get<1>(s[i]); }
47	  inline tuple<uintE, data> vtxAndData(const uintE& i) const { return s[i]; }
48	
49	  // Dense
50	  inline bool isIn(const uintE& v) const { return std::get<0>(d[v]); }
51	  inline data& ithData(const uintE& v) const { return std::get<1>(d[v]); }
52	
53	  // Returns (uintE) -> Maybe<tuple<vertex, vertex-data>>.
54	  auto get_fn_repr() const {
55	    std::function<Maybe<tuple<uintE, data>>(const uintE&)> fn;
56	    if (isDense) {
57	      fn = [&] (const uintE& v) -> Maybe<tuple<uintE, data>> {
58	        auto ret = Maybe<tuple<uintE, data>>(make_tuple(v, std::get<1>(d[v])));
59	        ret.exists = std::get<0>(d[v]);
60	        return ret;
61	      };
62	    } else {
63	      fn = [&] (const uintE& i) -> Maybe<tuple<uintE, data>> {
64	        return Maybe<tuple<uintE, data>>(s[i]);
65	      };
66	    }
67	    return fn;
68	  }
69	
70	  long size() const { return m; }
71	  long numVertices() const { return n; }
72	
73	  long numRows() const { return n; }
74	  long numNonzeros() const { return m; }
75	
76	  bool isEmpty() const { return m==0; }
77	  bool dense() const { return isDense; }
78	
79	  void toSparse() {
80	    if (s == NULL && m > 0) {
81	      auto f = make_in_imap<D>(n, [&] (size_t i) -> tuple<bool, data> { return d[i]; });
82	      auto out = pbbs::pack_index_and_data<uintE, data>(f, n);
83	      out.alloc = false;
84	      s = out.s;
85	      if (out.size() != m) {
86	        cout << "bad stored value of m" << endl;
87	        abort();
88	      }
89	    }
90	    isDense = false;
91	  }
92	
93	  // Convert to dense but keep sparse representation if it exists.
94	  void toDense() {
95	    if (d == NULL) {
96	      d = newA(D, n);
97	      {parallel_for(long i=0;i<n;i++) std::get<0>(d[i]) = false;}
98	      {parallel_for(long i=0;i<m;i++)
99	        d[std::get<0>(s[i])] = make_tuple(true, std::get<1>(s[i]));}
100	    }
101	    isDense = true;
102	  }
103	
104	
105	  S* s;
106	  D* d;
107	  size_t n, m;
108	  bool isDense;
109	};
