71	template <class vertex>
72	void Compute(graph<vertex>& GA, commandLine P) {
73	  long maxIters = P.getOptionLongValue("-maxiters",100);
74	  const long n = GA.n;
75	  const double damping = 0.85, epsilon = 0.0000001;
76	
77	  double one_over_n = 1/(double)n;
78	  double* p_curr = newA(double,n);
79	  {parallel_for(long i=0;i<n;i++) p_curr[i] = one_over_n;}
80	  double* p_next = newA(double,n);
