// Connected components by label propagation with pointer jumping.
//
// Every vertex starts as its own component label (IDs[i] = i) and each round
// propagates the smallest label seen so far along the edges (writeMin).  The
// labels therefore form a forest: IDs[i] is always the id of some vertex in
// i's component and IDs[x] <= x holds for every x.  In addition to the plain
// propagation of Components.C, each round finishes with a pointer-jumping
// (shortcutting) step, IDs[i] = IDs[IDs[i]], applied to the vertices whose
// label just changed.  Shortcutting collapses long chains in that forest, so a
// vertex hands its neighbours a much smaller label in the next round and the
// computation converges in fewer rounds.
//
// A vertex is kept in the frontier only while its label keeps changing, so the
// loop ends exactly when no label moved, which (on a symmetric graph) means
// every vertex holds the minimum id of its component.  The final labelling is
// therefore identical to the one computed by Components.C, not merely an
// equivalent partition.
#include "ligra.h"

// Update function: propagate the smaller label to d with writeMin.  prevIDs
// holds the label d had at the start of the round, so "the label was still
// prevIDs[d] before this write" identifies the first decrease of IDs[d] in
// this round and d is placed in the output frontier exactly once.
struct CC_F {
  uintE* IDs, *prevIDs;
  CC_F(uintE* _IDs, uintE* _prevIDs) :
    IDs(_IDs), prevIDs(_prevIDs) {}
  inline bool update(uintE s, uintE d) { //Update
    uintE origID = IDs[d];
    if(IDs[s] < origID) {
      IDs[d] = IDs[s];
      if(origID == prevIDs[d]) return 1;
    }
    return 0;
  }
  inline bool updateAtomic (uintE s, uintE d) { //atomic version of Update
    uintE origID = IDs[d];
    return (writeMin(&IDs[d],IDs[s]) && origID == prevIDs[d]);
  }
  //cond function is always true: a label may improve any number of times
  inline bool cond (uintE d) { return cond_true(d); }
};

//vertex map function used to sync prevIDs with IDs at the start of a round
struct CC_Vertex_F {
  uintE* IDs, *prevIDs;
  CC_Vertex_F(uintE* _IDs, uintE* _prevIDs) :
    IDs(_IDs), prevIDs(_prevIDs) {}
  inline bool operator () (uintE i) {
    prevIDs[i] = IDs[i];
    return 1;
  }
};

// Vertex filter function performing the pointer jumping: IDs[i] is replaced by
// IDs[IDs[i]], following the chain up to the root of i's label tree.  Because
// IDs[x] <= x for every x the chain strictly decreases, so it cannot cycle and
// the walk terminates; every label on it belongs to i's component, hence the
// jump never leaves the component and never increases a label.  Only IDs[i]
// itself is written -- a vertex outside the frontier must not have its label
// changed here, or the change would never be propagated to its neighbours.
// The vertex stays in the frontier only while its label keeps changing.
struct CC_Shortcut {
  uintE* IDs, *prevIDs;
  CC_Shortcut(uintE* _IDs, uintE* _prevIDs) :
    IDs(_IDs), prevIDs(_prevIDs) {}
  inline bool operator () (uintE i) {
    uintE l = IDs[i];
    while(l != IDs[l]) l = IDs[l]; //walk to the root of the label tree
    writeMin(&IDs[i],l);           //IDs[i] = IDs[IDs[i]] = ... = l
    return (prevIDs[i] != IDs[i]); //active only if the label changed
  }
};

template <class vertex>
void Compute(graph<vertex>& GA, commandLine P) {
  long n = GA.n;
  uintE* IDs = newA(uintE,n), *prevIDs = newA(uintE,n);
  {parallel_for(long i=0;i<n;i++) IDs[i] = i;} //initialize unique IDs
  {parallel_for(long i=0;i<n;i++) prevIDs[i] = i;}

  bool* frontier = newA(bool,n);
  {parallel_for(long i=0;i<n;i++) frontier[i] = 1;}
  vertexSubset Frontier(n,n,frontier); //initial frontier contains all vertices

  long rounds = 0;
  while(!Frontier.isEmpty()){ //iterate until IDs converge
    rounds++;
    //remember the label each active vertex starts the round with
    vertexMap(Frontier,CC_Vertex_F(IDs,prevIDs));
    //propagate the smallest label along the edges
    vertexSubset output = edgeMap(GA, Frontier, CC_F(IDs,prevIDs));
    //pointer jump on the vertices that just changed, keeping the ones that
    //really did change as the next frontier
    output.toDense(); //materialize the dense form here so that del() frees it
    vertexSubset next = vertexFilter(output, CC_Shortcut(IDs,prevIDs));
    Frontier.del(); output.del();
    Frontier = next;
  }
  Frontier.del();

  // Number of components = number of distinct labels.  At convergence every
  // vertex holds the smallest id of its component, so this also equals the
  // number of vertices i with IDs[i] == i, which is how Components.C counts.
  long* label_used = newA(long,n);
  {parallel_for(long i=0;i<n;i++) label_used[i] = 0;}
  {parallel_for(long i=0;i<n;i++) label_used[IDs[i]] = 1;}
  long components = sequence::plusReduce(label_used,n);

  cout << "Components-Shortcut rounds: " << rounds << endl;
  cout << "Components: " << components << endl;

  free(label_used); free(IDs); free(prevIDs);
}

